from taf.ul.ettf.logger import custom_logger, log
from taf.ul.ettf.utils.robot_handlers import with_callback_name
from ta5g_commissioning import ta5g_commissioning
from ta5g_enb import ta5g_enb


logger = custom_logger('Setups_Commissioning')


class Commissioning(object):
    def __init__(self, logs_directory):
        self.logs_directory = logs_directory

    @log('Commissioning started...', 'Commissioning finished', logger)
    def perform(self, commissioning, remote_host):
        ta5g_commissioning().find_scfc_and_fix_and_send_full_commissioning(
            scfc_filename=commissioning, output_dirpath=self.logs_directory, remote_host=remote_host
        )


class SwconfigFlags(object):
    def __init__(self, logs_directory):
        self.gnb = ta5g_enb()
        self.logs_directory = logs_directory

    @log('Setting swconfig flags...', 'Swconfig flags set', logger)
    def set(self, flags, remote_host):
        self.gnb.backup_and_modify_swconfig_file(parameters_list=flags,
                                                 output_dirpath=self.logs_directory,
                                                 remote_host=remote_host)

    @with_callback_name('Sw Config Flags Teardown')
    def sw_config_flags_teardown(self):
        self.gnb.put_original_swconfig_file_on_enb()
